let DEFAULT_SETTINGS={lat:null,lon:null,theme:"system",appearance:"standard",language:"system"},VALID_THEMES=["system","light","dark"],VALID_APPEARANCES=["standard","cool","pop"];export function getSettings(){let e=localStorage.getItem("omegaSettings");if(e)try{let t=JSON.parse(e),a={...DEFAULT_SETTINGS,...t};return VALID_THEMES.includes(a.theme)||(a.theme=DEFAULT_SETTINGS.theme),VALID_APPEARANCES.includes(a.appearance)||(a.appearance=DEFAULT_SETTINGS.appearance),a}catch(n){console.error("Failed to parse saved settings:",n)}return DEFAULT_SETTINGS}export function saveSettings(e){localStorage.setItem("omegaSettings",JSON.stringify(e))}